package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static ge.opensoft.openservice.EmployeeCasesAcceptance.result;
import static ge.opensoft.openservice.EmployeeCasesAcceptance.get;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import java.time.Instant;

final class ServiceOutagesAcceptance {
 static String api(String id){return "/api/openservice/configuration-items/"+id+"/outages";}
 static String time(long millis){return Instant.ofEpochMilli(millis).toString();}
 static String at(long seconds){return Instant.parse("2026-11-01T00:00:00Z").plusSeconds(seconds).toString();}
 static String ci(WorkflowSupport h)throws Exception{return TypedRelationshipsAcceptance.record(h,"cmdb_ci","Observed service CI");}
 static Map<String,Object> body(String kind,String begin,String end){return map("operation","create","record_revision",0,"request_id",id(),"kind",kind,"begin",begin,"end",end,"summary","Observed interruption <script>","evidence","Verified actual impact <script>");}
 static Map<String,Object> create(WorkflowSupport h,String ci,String kind,String begin,String end)throws Exception{return result(h.json("POST",api(ci),body(kind,begin,end),auth("admin")));}
 static Map<String,Object> entry(Map<String,Object> page,String id){return objects(page.get("outages")).stream().filter(r->r.get("outage_id").equals(id)).findFirst().orElseThrow();}
 static Map<String,Object> command(WorkflowSupport h,String ci,String id,String operation)throws Exception{var page=get(h,api(ci),"admin");return map("operation",operation,"record_revision",Integer.parseInt(object(page.get("record")).get("sys_mod_count").toString()),"outage_id",id,"revision",entry(page,id).get("revision"),"evidence","Reviewed recovery or cancellation evidence");}
 static Map<String,Object> close(WorkflowSupport h,String ci,String id,String end)throws Exception{var cmd=command(h,ci,id,"close");cmd.put("end",end);return result(h.json("POST",api(ci),cmd,auth("admin")));}
 static Map<String,Object> report(WorkflowSupport h,String ci,String start,String end)throws Exception{return object(get(h,api(ci)+"?start="+start+"&end="+end,"admin").get("report"));}
 static void run(WorkflowSupport h)throws Exception {
  String ci=ci(h);long now=System.currentTimeMillis();assertEquals("no_recorded_outage",get(h,api(ci),"admin").get("current_status"));var scheduled=create(h,ci,"planned",time(now+7200000),time(now+10800000));String future=scheduled.get("outage_id").toString();assertEquals("scheduled",entry(scheduled,future).get("status"));assertEquals("no_recorded_outage",scheduled.get("current_status"));String planned=create(h,ci,"planned",time(now-7200000),time(now+3600000)).get("outage_id").toString();String degraded=create(h,ci,"degradation",time(now-3600000),"").get("outage_id").toString();assertEquals("degradation",get(h,api(ci),"admin").get("current_status"));var input=body("outage",time(now-1800000),"");var result=result(h.json("POST",api(ci),input,auth("admin")));String outage=result.get("outage_id").toString();assertEquals("outage",result.get("current_status"));assertEquals(outage,result(h.json("POST",api(ci),input,auth("admin"))).get("outage_id"));assertEquals(4,objects(get(h,api(ci),"admin").get("outages")).size());assertEquals(1,objects(entry(get(h,api(ci),"admin"),outage).get("history")).size());assertEquals("degradation",close(h,ci,outage,time(now-60000)).get("current_status"));result(h.json("POST",api(ci),command(h,ci,degraded,"cancel"),auth("admin")));assertEquals("planned",get(h,api(ci),"admin").get("current_status"));close(h,ci,planned,time(now-1000));assertEquals("no_recorded_outage",get(h,api(ci),"admin").get("current_status"));new Store(h.environment);assertEquals("ended",entry(get(h,api(ci),"admin"),outage).get("status"));assertEquals(outage,result(h.json("POST",api(ci),input,auth("admin"))).get("outage_id"));result(h.json("POST",api(ci),command(h,ci,future,"cancel"),auth("admin")));assertEquals("cancelled",entry(get(h,api(ci),"admin"),future).get("status"));assertEquals(409,h.json("DELETE","/api/now/table/cmdb_ci/"+ci,map(),auth("admin")).statusCode());String ordinary=ci(h);assertEquals(204,h.json("DELETE","/api/now/table/cmdb_ci/"+ordinary,map(),auth("admin")).statusCode());
  try(var db=h.store.open()){assertEquals(8,db.count("SELECT COUNT(*) FROM os_event WHERE record_id=? AND action LIKE 'outage.%'",ci));}
 }
 static void intervals(WorkflowSupport h)throws Exception {
  String ci=ci(h);for(long[] interval:List.of(new long[]{10,40},new long[]{20,50},new long[]{70,90},new long[]{200,220}))create(h,ci,"outage",at(interval[0]),at(interval[1]));String extension=create(h,ci,"outage",at(5),at(15)).get("outage_id").toString();create(h,ci,"planned",at(0),at(100));create(h,ci,"degradation",at(30),at(80));var report=report(h,ci,at(0),at(100));assertEquals(100000,((Number)report.get("window_ms")).longValue());assertEquals(65000,((Number)report.get("unplanned_ms")).longValue());assertEquals(100000,((Number)report.get("planned_ms")).longValue());assertEquals(50000,((Number)report.get("degraded_ms")).longValue());assertEquals("35.0000",report.get("recorded_availability"));report=report(h,ci,at(30),at(80));assertEquals(30000,((Number)report.get("unplanned_ms")).longValue());assertEquals("40.0000",report.get("recorded_availability"));result(h.json("POST",api(ci),command(h,ci,extension,"cancel"),auth("admin")));assertEquals(60000,((Number)report(h,ci,at(0),at(100)).get("unplanned_ms")).longValue());assertEquals("100.0000",report(h,ci,at(300),at(400)).get("recorded_availability"));
  String epoch=ci(h);create(h,epoch,"outage","1970-01-01T00:00:00Z","1970-01-01T00:00:01Z");assertEquals("50.0000",report(h,epoch,"1970-01-01T00:00:00Z","1970-01-01T00:00:02Z").get("recorded_availability"));String ongoing=ci(h);create(h,ongoing,"outage",at(30),"");assertEquals("30.0000",report(h,ongoing,at(0),at(100)).get("recorded_availability"));assertEquals("0.0000",report(h,ongoing,at(40),at(50)).get("recorded_availability"));
 }
 static void boundaries(WorkflowSupport h)throws Exception {
  String ci=ci(h);assertEquals(401,h.get(api(ci),null).statusCode());assertEquals(405,h.json("DELETE",api(ci),map(),auth("admin")).statusCode());assertEquals(404,h.get(api(id()),auth("admin")).statusCode());for(String query:List.of("?offset=-1","?offset=1001","?end="+at(100),"?extra=true","?start="+at(0),"?start="+at(0)+"&end="+at(0),"?start="+at(1)+"&end="+at(0),"?start=1970-01-01T00:00:00Z&end="+at(0),"?start="+at(0)+"&end=2099-01-01T00:00:00Z"))assertEquals(400,h.get(api(ci)+query,auth("admin")).statusCode());
  for(var invalid:List.of(map("extra",1),map("operation","bad"),map("record_revision","0"),map("request_id","guessable"),map("kind","unknown"),map("summary",""),map("evidence",""),map("begin","bad"),map("begin","1969-01-01T00:00:00Z"),map("begin","2099-01-01T00:00:00Z"),map("begin","2026-11-01T00:00:00+00:00"),map("begin","2026-11-01T00:00:00.000000001Z"),map("end",1),map("end",at(0)),map("end","1970-01-01T00:00:00Z"),map("kind","planned","end",""),map("kind","planned","begin","1970-01-01T00:00:00Z","end",at(100)))){var body=body("outage",at(0),at(100));body.putAll(invalid);assertEquals(400,h.json("POST",api(ci),body,auth("admin")).statusCode(),invalid.toString());}
  var input=body("outage",at(0),"");var page=result(h.json("POST",api(ci),input,auth("admin")));String outage=page.get("outage_id").toString();var changed=new LinkedHashMap<>(input);changed.put("summary","Different observation");assertEquals(409,h.json("POST",api(ci),changed,auth("admin")).statusCode());var cmd=command(h,ci,outage,"close");cmd.put("end",at(100));for(var invalid:List.of(map("extra",1),map("evidence",""),map("end",at(0)))){var bad=new LinkedHashMap<>(cmd);bad.putAll(invalid);assertEquals(400,h.json("POST",api(ci),bad,auth("admin")).statusCode());}var missing=new LinkedHashMap<>(cmd);missing.put("outage_id",id());assertEquals(404,h.json("POST",api(ci),missing,auth("admin")).statusCode());for(String field:List.of("record_revision","revision")){var stale=new LinkedHashMap<>(cmd);stale.put(field,99);assertEquals(409,h.json("POST",api(ci),stale,auth("admin")).statusCode());}result(h.json("POST",api(ci),cmd,auth("admin")));var repeated=command(h,ci,outage,"close");repeated.put("end",at(110));assertEquals(409,h.json("POST",api(ci),repeated,auth("admin")).statusCode());result(h.json("POST",api(ci),command(h,ci,outage,"cancel"),auth("admin")));assertEquals(409,h.json("POST",api(ci),command(h,ci,outage,"cancel"),auth("admin")).statusCode());String planned=create(h,ci,"planned",at(10),at(20)).get("outage_id").toString();var after=command(h,ci,planned,"close");after.put("end",at(30));assertEquals(409,h.json("POST",api(ci),after,auth("admin")).statusCode());
 }
 static void authority(WorkflowSupport h)throws Exception {
  h.account("OutageOperator","agent");h.account("OutageOther","agent");h.account("OutageReader","reader");String ci=ci(h);assertEquals(403,h.get(api(ci),auth("OutageReader")).statusCode());var body=body("outage",at(1),"");var result=result(h.json("POST",api(ci),body,auth("OutageOperator")));String outage=result.get("outage_id").toString();assertEquals(403,h.json("POST",api(ci),body,auth("OutageReader")).statusCode());ProblemInvestigationsAcceptance.access(h,"cmdb_ci",ci,"private",FieldDispatchAcceptance.uid(h,"OutageOperator"));assertEquals(404,h.get(api(ci),auth("OutageOther")).statusCode());assertEquals(404,h.json("POST",api(ci),body,auth("OutageOther")).statusCode());ProblemInvestigationsAcceptance.access(h,"cmdb_ci",ci,"workspace","");
  Map<String,Object> original;try(var db=h.store.open()){original=Service.schema(db,"cmdb_ci");}var hidden=new LinkedHashMap<>(original);hidden.put("field_rules",map("short_description",map("type","string","read_roles",List.of("admin"))));ReferencePickerAcceptance.writeSchema(h,"cmdb_ci",hidden);try{assertFalse(object(get(h,api(ci),"OutageOperator").get("record")).containsKey("short_description"));}finally{ReferencePickerAcceptance.writeSchema(h,"cmdb_ci",original);}
  var cmd=command(h,ci,outage,"cancel");for(String permission:List.of("read","update")){var denied=new LinkedHashMap<>(original);var roles=new LinkedHashMap<>(object(original.getOrDefault("record_roles",map())));roles.put(permission,List.of("agent"));denied.put("record_roles",roles);ReferencePickerAcceptance.writeSchema(h,"cmdb_ci",denied);try{assertEquals(403,h.json("POST",api(ci),cmd,auth("admin")).statusCode());if(permission.equals("read"))assertEquals(403,h.get(api(ci),auth("admin")).statusCode());else assertEquals(false,get(h,api(ci),"admin").get("can_edit"));}finally{ReferencePickerAcceptance.writeSchema(h,"cmdb_ci",original);}}
  result(h.json("PATCH","/api/now/table/cmdb_ci/"+ci,map("description","Updated CI after review"),auth("admin")));assertEquals(409,h.json("POST",api(ci),cmd,auth("admin")).statusCode());assertEquals(409,h.json("POST",api(ci),body,auth("OutageOperator")).statusCode());result(h.json("POST",api(ci),command(h,ci,outage,"cancel"),auth("admin")));
 }
 static void concurrency(WorkflowSupport h)throws Exception {
  String ci=ci(h);var body=body("outage",at(1),"");String outage;try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var start=new java.util.concurrent.CountDownLatch(1);var a=pool.submit(()->{start.await();return result(h.json("POST",api(ci),body,auth("admin")));});var b=pool.submit(()->{start.await();return result(h.json("POST",api(ci),body,auth("admin")));});start.countDown();outage=a.get().get("outage_id").toString();assertEquals(outage,b.get().get("outage_id"));}var close=command(h,ci,outage,"close");close.put("end",at(100));try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var start=new java.util.concurrent.CountDownLatch(1);var a=pool.submit(()->{start.await();return h.json("POST",api(ci),close,auth("admin")).statusCode();});var b=pool.submit(()->{start.await();return h.json("POST",api(ci),close,auth("admin")).statusCode();});start.countDown();assertEquals(Set.of(200,409),Set.of(a.get(),b.get()));}try(var db=h.store.open()){assertEquals(1,db.count("SELECT COUNT(*) FROM os_ci_outage"));assertEquals(2,db.count("SELECT COUNT(*) FROM os_outage_history"));}
 }
 static void capacity(WorkflowSupport h)throws Exception {
  String ci=ci(h);var body=body("outage",at(0),at(100));String outage=result(h.json("POST",api(ci),body,auth("admin"))).get("outage_id").toString();try(var db=h.store.open()){var row=db.one("SELECT * FROM os_ci_outage WHERE outage_id=?",outage);for(int n=1;n<1000;n++)db.update("INSERT INTO os_ci_outage(outage_id,record_id,request_id,fingerprint,kind,summary,begin_ms,end_ms,cancelled,revision) VALUES(?,?,?,?,?,?,?,?,0,1)",id(),ci,id(),row.get("fingerprint"),"outage","Retained interval "+n,row.get("begin_ms"),row.get("end_ms"));db.connection.commit();}var page=get(h,api(ci),"admin");assertEquals(100,objects(page.get("outages")).size());assertEquals(true,page.get("truncated"));var second=get(h,api(ci)+"?offset=100","admin");assertEquals(100,objects(second.get("outages")).size());var seen=new HashSet<String>();for(int offset=0;offset<1000;offset+=100)for(var row:objects(get(h,api(ci)+"?offset="+offset,"admin").get("outages")))assertTrue(seen.add(row.get("outage_id").toString()));assertEquals(1000,seen.size());assertTrue(objects(get(h,api(ci)+"?offset=1000","admin").get("outages")).isEmpty());var last=get(h,api(ci)+"?offset=900","admin");assertEquals(-1,last.get("next_offset"));var older=objects(last.get("outages")).getLast();result(h.json("POST",api(ci),map("operation","cancel","record_revision",0,"outage_id",older.get("outage_id"),"revision",1,"evidence","Reviewed older retained evidence"),auth("admin")));assertEquals("cancelled",entry(get(h,api(ci)+"?offset=900","admin"),older.get("outage_id").toString()).get("status"));assertEquals(outage,result(h.json("POST",api(ci),body,auth("admin"))).get("outage_id"));assertEquals(400,h.json("POST",api(ci),body("degradation",at(0),at(10)),auth("admin")).statusCode());assertEquals(100000,((Number)report(h,ci,at(0),at(200)).get("unplanned_ms")).longValue());
 }
}
